886	void LiaStarExtension::addEnumLemma(Node lemma)
887	{
888	  // Queue a main-solver enumeration lemma. A lemma that rewrites to a
889	  // constant carries no information and is rejected downstream
890	  // (TheoryInferenceManager asserts lemmas are not constant), so skip it.
891	  if (rewrite(lemma).isConst())
892	  {
893	    return;
894	  }
895	  d_im.addPendingLemma(lemma, InferenceId::ARITH_LIA_STAR_ENUM);
896	}
