650	void LiaStarExtension::addCone(
651	    Node n, const std::pair<std::vector<std::string>, Node>& pair)
652	{
653	  // Lazy path: build the cone for a single disjunct `pair` and append it to the
654	  // cones accumulated so far for this lambda (n[0]). An empty (infeasible) cone
655	  // is dropped.
656	  size_t dimension = n.getNumChildren() - 1;
657	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones =
658	      d_lazyCones[n[0]];
659	
660	  Trace("liastar-ext") << "---------------------------" << std::endl;
661	  Trace("liastar-ext") << "Cone for node " << std::endl
662	                       << pair.second << std::endl;
663	
664	  Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
665	  if (LiaStarUtils::isEmptyCone(cone))
666	  {
667	    Trace("liastar-ext") << "empty cone" << std::endl;
668	    return;
669	  }
670	  cones.push_back({pair.second, cone});
671	}
