928	        std::pair<std::vector<std::string>, Node> m =
929	            getMatrix(variables, n[i]);
930	        constraints.push_back(m.first[0]);
931	      }
932	      return {constraints, n};
933	    }
934	
935	    default:
936	    {
937	      InternalError() << "Unexpected kind. Node " << n
